@pytest.mark.parametrize("scenario_case", _PARAM_CASES, ids=_PARAM_IDS)
def test_webhook_post_schema_conforms_to_spec_for_actual_status(api_client, config_test_data, validator, scenario_case):
    """
    Schema conformance check:
    - Sends a minimally-populated payload (scope only if available), allowing server to respond accordingly.
    - Validates using the actual status code if explicitly defined in the spec; otherwise, falls back to 'default'.
    - Ensures we cover both success and error schema validations across scenario rows.
    """
    # Use scope-only payload if available; this is intentionally minimal, may trigger default error.
    minimal_payload: Dict[str, Any] = {}
    scope_obj: Dict[str, Any] = {}
    if scenario_case.get("scope-id"):
        scope_obj["id"] = scenario_case["scope-id"]
    if scenario_case.get("scope-type"):
        scope_obj["type"] = scenario_case["scope-type"]
    if scope_obj:
        minimal_payload["scope"] = scope_obj

    resp = api_client.post(_ENDPOINT, json_body=minimal_payload or None, headers={"Content-Type": "application/json"})
    assert resp is not None, "No response returned"

    status_str = str(resp.status_code)
    # Try direct status validation; if not defined in spec, fall back to 'default'
    direct = validator.validate_schema_by_response(_ENDPOINT, _METHOD, status_str, resp)
    if direct.get("valid"):
        return
    if "No response block" in (direct.get("message") or ""):
        # Fallback to default
        fallback = validator.validate_schema_by_response(_ENDPOINT, _METHOD, "default", resp)
        if not fallback.get("valid"):
            msg = fallback.get("message", "Schema validation failed")
            pytest.fail(f"Response schema invalid for default block. Status={resp.status_code}; msg={msg}; body={resp.text}")
    else:
        msg = direct.get("message", "Schema validation failed")
        pytest.fail(f"Response schema invalid for status {status_str}. msg={msg}; body={resp.text}")
